def _md_html_impl(ctx):
    out = ctx.actions.declare_file(ctx.label.name + ".html")
    ctx.actions.run(
        executable = ctx.executable._pandoc,
        arguments = ["-o", out.path, ctx.file.src.path],
        inputs = [ctx.file.src],
        outputs = [out],
    )
    return [DefaultInfo(files = depset([out]))]

md_html = rule(
    implementation = _md_html_impl,
    attrs = {
        "src": attr.label(allow_single_file = [".md"]),
        "_pandoc": attr.label(default = "//tools/pandoc", executable = True, cfg = "exec"),
    },
)

def service_deps(service, extra = []):
    """Returns the standard dependency labels for a service package."""
    base = [
        "//libs/log",
        "//libs/metrics",
        "//services/%s/proto:%s_go_proto" % (service, service),
    ]
    return base + extra

def image_tag(version, env):
    return "%s-%s" % (version, env)

def _copy_to_dir_impl(ctx):
    outs = []
    for src in depset(ctx.files.srcs).to_list():
        out = ctx.actions.declare_file(ctx.attr.out_dir + "/" + src.basename)
        ctx.actions.symlink(output = out, target_file = src)
        outs.append(out)
    return [DefaultInfo(files = depset(outs))]

copy_to_dir = rule(
    implementation = _copy_to_dir_impl,
    attrs = {
        "srcs": attr.label_list(allow_files = True),
        "out_dir": attr.string(mandatory = True),
    },
)
